// Source-first variation pricing. No product records are created by this helper.
const units={ml:{kind:'volume',factor:1},l:{kind:'volume',factor:1000},g:{kind:'mass',factor:1},kg:{kind:'mass',factor:1000},ha:{kind:'area',factor:1}};
function quantity(value) {
  const match=String(value).trim().toLowerCase().match(/^(\d+(?:[.,]\d+)?)\s*(ml|l|kg|g|ha)$/);
  if(!match || Number(match[1].replace(',','.'))<=0) throw new Error('UNSUPPORTED_SOURCE_QUANTITY');
  const unit=units[match[2]];
  return {kind:unit.kind,amount:Number(match[1].replace(',','.'))*unit.factor};
}
function price({basePrice,baseQuantity,targetQuantity,sourcePrice=null,decimals=2}) {
  if(!Number.isInteger(decimals)||decimals<0||decimals>6) throw new Error('INVALID_CURRENCY_PRECISION');
  const valid=value=>typeof value==='number'&&Number.isFinite(value)&&value>=0;
  if(sourcePrice!==null) {
    if(!valid(sourcePrice)) throw new Error('INVALID_SOURCE_PRICE');
    return {price:sourcePrice,provenance:'figma-explicit',calculated:false};
  }
  if(!valid(basePrice)) throw new Error('SOURCE_BASE_PRICE_REQUIRED');
  const base=quantity(baseQuantity),target=quantity(targetQuantity);
  if(base.kind!==target.kind) throw new Error('INCOMPATIBLE_VARIATION_UNITS');
  const amount=basePrice*target.amount/base.amount;
  return {price:Math.round((amount+Number.EPSILON)*10**decimals)/10**decimals,
    provenance:'user-authorized-proportional',calculated:true,basePrice,baseQuantity,targetQuantity,decimals};
}
function mayUpdate({current,lastImported,owned}) {
  return owned===true && lastImported!==undefined && current===lastImported;
}
module.exports={price,quantity,mayUpdate};
if(require.main===module) {
  try { console.log(JSON.stringify(price(JSON.parse(process.argv[2])))); }
  catch(e){console.error(e.message);process.exitCode=1;}
}
async function prepare({ page, route, baseUrl }) {
  const visit = async (url) => {
    await page.goto(url, { waitUntil: 'domcontentloaded' });
    await page.waitForTimeout(350);
  };
  if (route.id === 'checkout-login' || route.id === 'checkout-registration') {
    await visit(`${baseUrl}/koszyk/`);
    while (await page.locator('.woocommerce-cart-form .remove').count()) {
      await page.locator('.woocommerce-cart-form .remove').first().click();
      await page.waitForTimeout(350);
    }
    await visit(`${baseUrl}/zamowienie/`);
    if (route.id === 'checkout-registration') {
      await page.locator('[data-checkout-registration-open]').click();
      await page.locator('[data-factory-section="account-registration-dialog"] input').first().waitFor({ state: 'visible' });
    }
    return;
  }
  if (route.id === 'cart' || route.id === 'checkout') {
    await visit(`${baseUrl}/koszyk/`);
    while (await page.locator('.woocommerce-cart-form .remove').count()) {
      await page.locator('.woocommerce-cart-form .remove').first().click();
      await page.waitForTimeout(350);
    }
    await visit(`${baseUrl}/produkt/aquatos-5l/`);
    const size = page.locator('select[name^="attribute_"]').first();
    if (await size.count()) await size.selectOption({ label: '5 L' });
    await page.locator('.single_add_to_cart_button:not(.disabled)').waitFor({ state: 'visible' });
    await page.locator('.single_add_to_cart_button').click();
    await page.waitForTimeout(500);
    await visit(`${baseUrl}/koszyk/`);
    const coupon = page.locator('#coupon_code');
    if (await coupon.count()) {
      await coupon.fill('BLACKFRIDAY');
      await page.locator('button[name="apply_coupon"]').click();
      await page.waitForTimeout(500);
      // This consumes WooCommerce's transient success notice while retaining
      // the source-backed applied coupon in the real cart session.
      await visit(`${baseUrl}/koszyk/`);
    }
    if (route.id === 'checkout') await visit(`${baseUrl}/zamowienie/`);
    return;
  }
  if (route.id === 'product-bundle') await page.goto(`${baseUrl}/produkt/pakiet-ochronny-rzepaku-ozimego-12-ha/`, { waitUntil: 'networkidle' });
  const selectors = { 'product-expanded': '[data-product-tab="use"]', 'product-inquiry': '[data-product-inquiry-open]', 'product-reviews-state': '[data-product-tab="reviews"]', 'product-files-state': '[data-product-tab="downloads"]' };
  const selector = selectors[route.id];
  if (selector) await page.locator(selector).click();
}
module.exports = { prepare };

